export default function Icon({ name, size = 20, className, style, title }) {
  const paths = PATHS[name]
  if (!paths) return null
  return (
    <svg
      viewBox="0 0 512 512"
      width={size}
      height={size}
      fill="currentColor"
      className={className ? `icon ${className}` : 'icon'}
      style={style}
      aria-hidden={title ? undefined : true}
      role={title ? 'img' : undefined}
      aria-label={title}
      dangerouslySetInnerHTML={{ __html: paths }}
    />
  )
}

/** Same icon as an HTML string, for places that build raw HTML (Leaflet divIcon). */
export function iconHtml(name, size = 20) {
  const paths = PATHS[name]
  if (!paths) return ''
  return `<svg viewBox="0 0 512 512" width="${size}" height="${size}" fill="currentColor" aria-hidden="true" class="icon">${paths}</svg>`
}
